-- >>> MIGRATION: 20260726010000_create_invoices.sql <<<
-- 20260726010000_create_invoices.sql
--
-- PROPOSAL-002 Phase 1, task 1.1. The anchor table for the financial ledger — see
-- ai_docs/FINANCE_TRACKER.md "Phase 1 — Financial Ledger Spine" for the full task breakdown
-- and ai_docs/PROPOSALS.md PROPOSAL-002 Phase 1 for the design rationale.
--
-- Why this exists instead of more columns on reservations (RISK-010): a reservation row is
-- mutated repeatedly across its lifecycle (status, doctor, notes, service list), so nothing
-- prevents a later edit from silently changing a figure that must never change once money has
-- changed hands. An invoice is an event record: written once at issue time, never updated
-- (only voided). grand_total is stored tax-inclusive with tax_rate on invoice_lines, not here
-- (DEC-021) — a tax split stays derivable without storing it redundantly at invoice level.
--
-- Idempotent: safe to re-run.

CREATE TABLE IF NOT EXISTS public.invoices (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_no      text UNIQUE NOT NULL,
  reservation_id  uuid REFERENCES public.reservations(id) ON DELETE SET NULL,
  customer_id     uuid REFERENCES public.customers(id) ON DELETE SET NULL,
  branch_id       uuid REFERENCES public.branches(id) ON DELETE SET NULL,
  issued_at       timestamptz NOT NULL DEFAULT now(),
  subtotal        numeric NOT NULL DEFAULT 0,
  discount_total  numeric NOT NULL DEFAULT 0,
  grand_total     numeric NOT NULL DEFAULT 0,
  status          text NOT NULL DEFAULT 'issued' CHECK (status IN ('draft', 'issued', 'void')),
  is_opening      boolean NOT NULL DEFAULT false,
  created_at      timestamptz NOT NULL DEFAULT now()
);

-- Backs invoice_no formatting (application-side, see src/lib/ledger.ts formatInvoiceNo) —
-- gap-tolerant is fine (DEC-014: management accounting, not statutory bookkeeping), a DB
-- sequence just avoids an application-level race condition on the next number.
CREATE SEQUENCE IF NOT EXISTS public.invoice_no_seq START 1;

CREATE INDEX IF NOT EXISTS invoices_customer_id_idx ON public.invoices (customer_id);
CREATE INDEX IF NOT EXISTS invoices_reservation_id_idx ON public.invoices (reservation_id);
CREATE INDEX IF NOT EXISTS invoices_issued_at_idx ON public.invoices (issued_at);

ALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;


----------------------------------------------------------------------

-- >>> MIGRATION: 20260726010100_create_invoice_lines.sql <<<
-- 20260726010100_create_invoice_lines.sql
--
-- PROPOSAL-002 Phase 1, task 1.2. Depends on 20260726010000_create_invoices.sql.
--
-- package_id has NO foreign key constraint yet: public.packages does not exist until task
-- 1.5/1.6 (migrations run in filename order). The constraint is added by
-- 20260726010500_create_customer_packages.sql once packages exists — mirrors how
-- product_sales.customer_id got its FK in a later migration (20260725160000) once the
-- referenced table was in place. Do not "fix" this by reordering; it is intentional.
--
-- cogs_snapshot and commission_snapshot are nullable, not NOT NULL DEFAULT 0. Phase 1 alone
-- cannot populate them correctly: COGS needs Phase 2's service_consumables recipe, and
-- commission needs a doctor's contract terms applied at issue time. NULL honestly means
-- "not yet costed" — a future 0 would incorrectly claim "this line has zero cost."
--
-- Idempotent: safe to re-run.

CREATE TABLE IF NOT EXISTS public.invoice_lines (
  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id           uuid NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  line_type            text NOT NULL CHECK (line_type IN ('service', 'product', 'package')),
  service_id           bigint REFERENCES public.services(id) ON DELETE SET NULL,
  product_id           text REFERENCES public.inventory_products(id) ON DELETE SET NULL,
  package_id           uuid, -- FK added in 20260726010500_create_customer_packages.sql
  description          text NOT NULL,
  qty                  numeric NOT NULL DEFAULT 1,
  unit_price           numeric NOT NULL DEFAULT 0,
  discount             numeric NOT NULL DEFAULT 0,
  tax_rate             numeric NOT NULL DEFAULT 0,
  line_total           numeric NOT NULL DEFAULT 0,
  cogs_snapshot        numeric,
  commission_snapshot  numeric,
  provider_id          uuid REFERENCES public.providers(id) ON DELETE SET NULL,
  created_at           timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS invoice_lines_invoice_id_idx ON public.invoice_lines (invoice_id);
CREATE INDEX IF NOT EXISTS invoice_lines_provider_id_idx ON public.invoice_lines (provider_id);

