-- >>> MIGRATION: 20260729000000_fix_services_id_identity_generation.sql <<<
-- 20260729000000_fix_services_id_identity_generation.sql
--
-- Regression found live 2026-07-29: the 2026-07-26 "dev schema baseline" migration
-- (20260726000000_dev_schema_baseline.sql) recreated services.id as
-- `GENERATED ALWAYS AS IDENTITY`. The pre-baseline legacy schema had it as
-- `GENERATED BY DEFAULT AS IDENTITY` (see supabase/migrations/_legacy/*).
--
-- GENERATED ALWAYS rejects ANY insert/upsert statement that includes an explicit value for
-- the identity column, unless the statement uses `OVERRIDING SYSTEM VALUE` — which
-- @supabase/supabase-js's `.upsert()` does not add. Every write this app makes to `services`
-- (POST /api/services, used by the Services admin CRUD, Promotions, and Packages'
-- included-services picker) sends the full row INCLUDING `id` for existing rows
-- (`mapServiceToDb`: `if (s.id) row.id = s.id;`), so every upsert of an EXISTING service has
-- been silently failing with Postgres error 428C9 ("cannot insert a non-DEFAULT value into
-- column \"id\"") since the baseline migration — caught via a promotion appearing to save in
-- the admin UI (optimistic local state update) but never persisting or reaching the public site,
-- because `syncServicesToApi()` only console.errors a failed sync, with no user-facing alert.
--
-- Fix: switch the identity generation mode back to BY DEFAULT, matching the legacy schema and
-- restoring the ability to upsert existing rows with an explicit `id` while still auto-generating
-- one on INSERT when `id` is omitted (new-service creation is unaffected either way).

ALTER TABLE public.services ALTER COLUMN id SET GENERATED BY DEFAULT;


