-- >>> MIGRATION: 20260922000000_package_pulse_balance_to_columns.sql <<<
-- 20260922000000_package_pulse_balance_to_columns.sql
--
-- Brief 34B / RISK-096: move the per-patient package pulse balance off the shared
-- page_settings 'customer_package_pulses' JSON blob (one read-modify-write row for the whole
-- clinic, so concurrent consumes lose deductions) onto the real customer_packages columns,
-- with a per-usage audit table and an atomic consume function.
--
-- Idempotent: safe to re-run. NOT APPLIED BY THE ASSISTANT — the owner applies it manually.

-- 1) Per-usage audit table. customer_package_id + reservation_id is unique so a retried
--    consume for the same booking is idempotent at the database level.
CREATE TABLE IF NOT EXISTS public.package_pulse_usage (
  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_package_id  uuid NOT NULL REFERENCES public.customer_packages(id) ON DELETE CASCADE,
  reservation_id       uuid REFERENCES public.reservations(id) ON DELETE SET NULL,
  quantity_used        integer NOT NULL,
  remaining_after      integer NOT NULL,
  used_by              text,
  treatment_area       text,
  notes                text,
  created_at           timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS package_pulse_usage_customer_package_id_idx
  ON public.package_pulse_usage(customer_package_id);

CREATE UNIQUE INDEX IF NOT EXISTS package_pulse_usage_pkg_reservation_uq
  ON public.package_pulse_usage (customer_package_id, reservation_id)
  WHERE reservation_id IS NOT NULL;

ALTER TABLE public.package_pulse_usage ENABLE ROW LEVEL SECURITY;

-- 2) Atomic consume. The FOR UPDATE row lock is what serialises concurrent consumes — a bare
--    UPDATE cannot carry the idempotency read and the usage insert in the same statement.
--    'fully_used', never 'completed': the customer_packages CHECK is
--    ('active','expired','fully_used') (20260726010500_create_customer_packages.sql).
CREATE OR REPLACE FUNCTION public.consume_package_pulses(
  p_customer_package_id uuid,
  p_qty                 integer,
  p_reservation_id      uuid DEFAULT NULL,
  p_used_by             text DEFAULT NULL,
  p_treatment_area      text DEFAULT NULL,
  p_notes               text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_pkg      public.customer_packages%ROWTYPE;
  v_usage    public.package_pulse_usage%ROWTYPE;
  v_consumed integer;
BEGIN
  SELECT * INTO v_pkg
    FROM public.customer_packages
   WHERE id = p_customer_package_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer package not found';
  END IF;

  -- Idempotent replay: same (package, reservation) already consumed — return it, change nothing.
  IF p_reservation_id IS NOT NULL THEN
    SELECT * INTO v_usage
      FROM public.package_pulse_usage
     WHERE customer_package_id = p_customer_package_id
       AND reservation_id = p_reservation_id;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'consumed',         v_usage.quantity_used,
        'requested',        p_qty,
        'remaining',        v_pkg.pulses_remaining,
        'already_deducted', true,
        'used_total',       v_pkg.pulses_used,
        'total_pulses',     v_pkg.total_pulses
      );
    END IF;
  END IF;

  IF p_qty IS NULL OR p_qty <= 0 THEN
    RAISE EXCEPTION 'quantity of pulses to consume must be greater than 0';
  END IF;

  IF v_pkg.expires_at IS NOT NULL AND v_pkg.expires_at < now() THEN
    RAISE EXCEPTION 'package has expired';
  END IF;

  IF v_pkg.total_pulses IS NULL OR v_pkg.total_pulses <= 0 THEN
    RAISE EXCEPTION 'package pulse quota is not configured';
  END IF;

  IF v_pkg.pulses_remaining IS NULL OR v_pkg.pulses_remaining <= 0 THEN
    RAISE EXCEPTION 'package has 0 remaining pulses';
  END IF;

  v_consumed := least(p_qty, greatest(v_pkg.pulses_remaining, 0));

  UPDATE public.customer_packages
     SET pulses_used      = pulses_used + v_consumed,
         pulses_remaining = greatest(0, pulses_remaining - v_consumed),
         status           = CASE WHEN pulses_remaining - v_consumed <= 0
                                 THEN 'fully_used' ELSE status END
   WHERE id = p_customer_package_id
   RETURNING * INTO v_pkg;

  INSERT INTO public.package_pulse_usage
    (customer_package_id, reservation_id, quantity_used, remaining_after, used_by, treatment_area, notes)
  VALUES
    (p_customer_package_id, p_reservation_id, v_consumed, v_pkg.pulses_remaining,
     p_used_by, p_treatment_area, p_notes);

  RETURN jsonb_build_object(
    'consumed',         v_consumed,
    'requested',        p_qty,
    'remaining',        v_pkg.pulses_remaining,
    'already_deducted', false,
    'used_total',       v_pkg.pulses_used,
    'total_pulses',     v_pkg.total_pulses
  );
END;
$$;

-- PostgREST exposes every public function at /rest/v1/rpc/… to the anon key, which ships in the
-- browser bundle. Without this revoke anyone could drain any patient's pulses. (Contrast
-- next_invoice_no() in 20260726010600, which has no grants — harmless for a sequence, not here.)
REVOKE ALL ON FUNCTION public.consume_package_pulses(uuid, integer, uuid, text, text, text)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.consume_package_pulses(uuid, integer, uuid, text, text, text)
  TO service_role;


----------------------------------------------------------------------

-- >>> MIGRATION: 20260922000100_backfill_package_pulse_balances_from_blob.sql <<<
-- 20260922000100_backfill_package_pulse_balances_from_blob.sql
--
-- Brief 34B item 6 / RISK-096: one-time backfill from the page_settings
-- 'customer_package_pulses' JSON blob onto the real customer_packages columns +
-- package_pulse_usage rows.
--
-- Rules:
--   * The blob WINS unconditionally — it was the live source of truth while the native
--     columns were written best-effort (and depletion writes were rejected wholesale by the
--     'completed' status CHECK violation, so native rows are stale exactly for exhausted
--     packages).
--   * Rows already touched by the new code (i.e. that have package_pulse_usage rows) are
--     skipped — the migration is safe to run before the deploy and safe to re-run.
--   * remaining = 0 marks the row 'fully_used', which also repairs packages the CHECK
--     violation left 'active' after depletion.
--   * Anything unresolvable is listed via RAISE NOTICE, one line per customer_packages.id,
--     and left alone — never a guessed total.
--   * The page_settings row is NOT deleted — it is the rollback.
--
-- Run immediately before deploying the column-reading code, while reception is not
-- checking out. Idempotent: safe to re-run. NOT APPLIED BY THE ASSISTANT.

DO $$
DECLARE
  v_store           jsonb;
  v_cp              record;
  v_entry           jsonb;
  v_hist            jsonb;
  v_included        integer;
  v_used            integer;
  v_remaining       integer;
  v_reservation     uuid;
  v_qty             integer;
  v_remaining_after integer;
  v_used_at         timestamptz;
BEGIN
  SELECT ps.value INTO v_store
    FROM public.page_settings ps
   WHERE ps.key = 'customer_package_pulses';

  IF v_store IS NULL OR jsonb_typeof(v_store) <> 'object' THEN
    v_store := '{}'::jsonb;
  END IF;

  FOR v_cp IN SELECT * FROM public.customer_packages LOOP
    -- Never overwrite a balance the new RPC has already moved.
    IF EXISTS (
      SELECT 1 FROM public.package_pulse_usage u WHERE u.customer_package_id = v_cp.id
    ) THEN
      CONTINUE;
    END IF;

    v_entry := v_store -> (v_cp.id::text);

    IF v_entry IS NULL OR jsonb_typeof(v_entry) <> 'object' THEN
      IF v_cp.package_type = 'pulses' AND COALESCE(v_cp.total_pulses, 0) <= 0 THEN
        RAISE NOTICE 'customer_packages %: pulses package with no pulse-store entry and no total_pulses — set Total Pulses in Admin → Packages', v_cp.id;
      END IF;
      CONTINUE;
    END IF;

    v_included := CASE
      WHEN COALESCE(v_entry->>'included_pulses', '') ~ '^\d+$'
        THEN (v_entry->>'included_pulses')::integer
      ELSE NULL END;
    v_used := CASE
      WHEN COALESCE(v_entry->>'used_pulses', '') ~ '^\d+$'
        THEN (v_entry->>'used_pulses')::integer
      ELSE 0 END;
    v_remaining := CASE
      WHEN COALESCE(v_entry->>'remaining_pulses', '') ~ '^\d+$'
        THEN (v_entry->>'remaining_pulses')::integer
      WHEN v_included IS NOT NULL THEN greatest(v_included - v_used, 0)
      ELSE NULL END;

    IF v_included IS NULL AND v_remaining IS NULL THEN
      RAISE NOTICE 'customer_packages %: malformed pulse-store entry — not backfilled', v_cp.id;
      CONTINUE;
    END IF;

    v_remaining := COALESCE(v_remaining, 0);

    UPDATE public.customer_packages
       SET total_pulses     = COALESCE(v_included, total_pulses),
           pulses_used      = v_used,
           pulses_remaining = v_remaining,
           status           = CASE WHEN v_remaining <= 0 THEN 'fully_used' ELSE status END
     WHERE id = v_cp.id;

    IF jsonb_typeof(v_entry->'usage_history') = 'array' THEN
      FOR v_hist IN SELECT * FROM jsonb_array_elements(v_entry->'usage_history') LOOP
        -- A well-formed UUID booking_id that no longer matches a live reservation (deleted test
        -- data, or any historical booking that was removed) must NOT be inserted, or the
        -- package_pulse_usage.reservation_id FK rejects the whole backfill (confirmed live,
        -- 2026-09-23: dev push failed 23503 on exactly this). Treat it the same as a malformed
        -- id: keep the usage row for audit history, but with reservation_id NULL.
        v_reservation := CASE
          WHEN COALESCE(v_hist->>'booking_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               AND EXISTS (
                 SELECT 1 FROM public.reservations r WHERE r.id = (v_hist->>'booking_id')::uuid
               )
            THEN (v_hist->>'booking_id')::uuid
          ELSE NULL END;
        v_qty := CASE
          WHEN COALESCE(v_hist->>'quantity_used', '') ~ '^\d+$'
            THEN (v_hist->>'quantity_used')::integer
          ELSE 0 END;
        v_remaining_after := CASE
          WHEN COALESCE(v_hist->>'remaining_after', '') ~ '^\d+$'
            THEN (v_hist->>'remaining_after')::integer
          ELSE v_remaining END;
        BEGIN
          v_used_at := (v_hist->>'used_at')::timestamptz;
        EXCEPTION WHEN OTHERS THEN
          v_used_at := now();
        END;

        INSERT INTO public.package_pulse_usage
          (customer_package_id, reservation_id, quantity_used, remaining_after,
           used_by, treatment_area, notes, created_at)
        VALUES
          (v_cp.id, v_reservation, v_qty, v_remaining_after,
           v_hist->>'used_by', v_hist->>'treatment_area', v_hist->>'notes', v_used_at)
        ON CONFLICT DO NOTHING;
      END LOOP;
    END IF;
  END LOOP;
END $$;


----------------------------------------------------------------------

-- >>> MIGRATION: 20260923000000_add_laser_deficit_resolution_to_reservations.sql <<<
-- 20260923000000_add_laser_deficit_resolution_to_reservations.sql
--
-- Brief 35 / DEC-079: a queryable marker recording how a laser-pulse deficit on a
-- reservation was resolved at reception checkout ('BUY_NEW_PACKAGE' or
-- 'PAY_PER_PULSE'), and how many deficit pulses it covered. It is the
-- reservation-level idempotency key for POST /api/reservations/laser-deficit —
-- the package_pulse_usage unique index only protects the pulse consume, not the
-- invoice line or the package sale.
--
-- Nullable, no default: bookings without a deficit (or predating this column)
-- stay NULL. NOT APPLIED BY THE ASSISTANT — the owner applies migrations.

ALTER TABLE public.reservations
  ADD COLUMN IF NOT EXISTS laser_deficit_resolution text,
  ADD COLUMN IF NOT EXISTS laser_deficit_pulses integer;

COMMENT ON COLUMN public.reservations.laser_deficit_resolution IS
  'How a delivered-pulses deficit was resolved at reception: BUY_NEW_PACKAGE or PAY_PER_PULSE. NULL = no deficit resolved (or none existed). Brief 35 / DEC-079.';
COMMENT ON COLUMN public.reservations.laser_deficit_pulses IS
  'Pulses delivered beyond the source package balance at resolution time. Paired with laser_deficit_resolution.';


